  class: net.officefloor.hq.app.settings.RefuseViewer
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGenerated
# Add a pool: a name (required, trimmed, unique on the sheet). Answers the sheet's pools.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.pool.ValidatePool
  next: save
