import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';

/**
 * The people table. A feature that shows something per person adds a column (a heading in
 * PersonColumnHead and a <td> in PersonCells) or rows under the person's own row (PersonDetail,
 * each contribution rendering its own <tr>, spanning PERSON_ROW_SPAN columns). All of it sits
 * inside the person's `person-row-<id>` element.
 */
export const PersonColumnHead = defineSlot<{ sheetId: string }>('person.columnHead');
export const PersonCells = defineSlot<{ sheetId: string; personId: number }>('person.cells');
export const PersonDetail = defineSlot<{ sheetId: string; personId: number }>('person.detail');

/** colSpan for a PersonDetail row: wide enough for every column. */
export const PERSON_ROW_SPAN = 100;
import { defineSlot } from '../Slot';

/**
 * The body of the active sheet, rendered once a user is signed in and a sheet is loaded. A
 * feature that shows or changes a sheet's data fills this region. Its data lives under query
 * keys starting ['sheet', sheetId, ...]: loading a sheet drops every such key, so the whole
 * sheet is re-read from the store.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { patronsKey, usePatrons, usePeople, type Person } from '../people/usePeople';
import { useClaims } from '../claims/useClaims';
import { hundredths, money, sumDues } from '../rates/useRates';
import { useSheetToday } from '../today/useSheetToday';

/** The first day (yyyy-mm-dd) of the 90 days up to and including a day. */
function windowStart(today: string): string {
  return new Date(Date.parse(`${today}T00:00:00Z`) - 89 * 86_400_000).toISOString().slice(0, 10);
}

/** Shares (in hundredths) for patrons in the order they were named: 100.00 split equally, each share rounded
 *  half to even to two decimals, the remainder (100.00 less the shares added up) given to the first-named. */
function shares(count: number): bigint[] {
  if (count === 0) return [];
  const n = BigInt(count);
  let each = 10000n / n;
  const rest = 10000n % n;
  if (rest * 2n > n || (rest * 2n === n && each % 2n === 1n)) each += 1n;
  const all = Array.from({ length: count }, () => each);
  all[0] += 10000n - each * n;
  return all;
}

/** A person's patrons: the other people on the sheet they have named, each with a share (shown as
 *  `<name> <share>`, sorted by name, comma and space separated), their backing (over their patrons, the patron's
 *  figure — the due frozen when each of their SETTLED claims dated within the 90 days up to and including the
 *  sheet's today was settled, added up — times their share divided by 100, added up and rounded half to even;
 *  0.00 with none), and a picker that names one more. Naming themselves, or a patron twice, is refused. */
function PersonPatrons({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const patrons = usePatrons(sheetId);
  const claims = useClaims(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');

  const named = (patrons.data ?? [])
    .filter((x) => x.personId === personId)
    .map((x) => people.data?.find((p) => p.id === x.patronId))
    .filter((p): p is Person => p !== undefined);
  const split = shares(named.length);
  const labels = named
    .map((p, i) => ({ name: p.name, share: split[i] }))
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    .map((x) => `${x.name} ${money(x.share)}`);
  const from = today === undefined ? undefined : windowStart(today);
  const figure = (patronId: number) => hundredths(sumDues((claims.data ?? [])
    .filter((c) => c.personId === patronId && c.status === 'SETTLED' && c.due !== null
      && from !== undefined && today !== undefined && c.date >= from && c.date <= today)
    .map((c) => c.due as string)));
  // In 1/10000 of a hundredth: figure (hundredths) times share (hundredths of a percent).
  const signed = named.reduce((sum, p, i) => sum + figure(p.id) * split[i], 0n);
  const size = signed < 0n ? -signed : signed;
  let cents = size / 10000n;
  const rest = size % 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  const backing = money(signed < 0n ? -cents : cents);

  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/patrons`, { patronId }),
    onSuccess: async () => {
      setChosen('');
      await queryClient.invalidateQueries({ queryKey: patronsKey(sheetId) });
    },
  });

  return (
    <>
      <td data-testid="person-patrons">{labels.join(', ')}</td>
      <td data-testid="person-backing">{backing}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={chosen}
          onChange={(e) => {
            setChosen(e.target.value);
            add.reset();
          }}
        >
          <option value="">Patron…</option>
          {(people.data ?? []).map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending}
          onClick={() => {
            add.reset();
            add.mutate(Number(chosen));
          }}
        >
          Add patron
        </button>
        {add.isError && <span data-testid="person-patron-error">{add.error.message}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({
    order: 50,
    Component: () => (
      <>
        <th>Patrons</th>
        <th>Backing</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 50, Component: PersonPatrons }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A member of a pool: a person (by id, and their name now) or another pool (`pool`, its name; `personId` then
 *  null), their share percent (two decimals), whether they are retired (a person with a retirement date set,
 *  whatever the date: they get no cut, their share spread over the others, but it counts in the total share) and their cut of the pool's pot (two decimals; null when
 *  the pool is not balanced, has no pot or has only retired members: a pool that is a member of another has its cut there as its pot; null
 *  too for a member that is not current), the membership's from-date and to-date (null when not given) and whether
 *  they include the sheet's today (a member that is not current counts in neither the total share nor the balance). */
export type PoolMember = {
  personId: number | null;
  pool: string | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string | null;
  from: string | null;
  to: string | null;
  current: boolean;
};

/** A pool: its name, its members in the order they were added, the total of their shares (two decimals)
 *  and whether that total is exactly 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

export function poolsKey(sheetId: string) {
  return ['sheet', sheetId, 'pools'];
}

/** The sheet's pools, by name. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: async () => (await getJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`)).pools,
  });
}

